{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "A close morphinan analogue, dihydromorphine, showed essentially no CNS accumulation by whole-body autoradiography in mice, directly supporting poor CNS access for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Mefenamic acid glucuronide, a carboxylate glucuronide conjugate, showed negligible brain uptake after oral administration in rats, indicating that glucuronide conjugation severely limits BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Zidovudine glucuronide (GAZT) had a CSF/plasma ratio of only 0.04 in monkeys, 10-fold lower than the parent drug, demonstrating that glucuronide conjugates have very poor CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Naloxegol, a polar PEGylated morphinan, showed limited BBB penetration in rats with a CSF/plasma ratio of 15%, supporting that polar morphinan derivatives are peripherally restricted.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Quercetin-3-O-glucuronide was detected in perfused brain tissue, showing that some glucuronide conjugates can achieve BBB penetration; however, this positive result is structurally distant from the morphinan glucuronide query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is morphine-3-glucuronide, a zwitterionic glucuronide conjugate of a morphinan. Multiple direct glucuronide-conjugate studies show negligible-to-poor brain/CSF uptake, and polar morphinan derivatives are peripherally restricted. The single positive quercetin glucuronide result is insufficient to override the consistent poor CNS access pattern. Prediction: fail.",
  "evidence_gaps": [
    "No direct in vivo brain or CSF measurement for the exact query molecule.",
    "Possible active uptake via sugar/glucuronide transporters was not experimentally assessed.",
    "Human data for the exact conjugate are absent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

